UIRubbleEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,100);this.particleClass=UIDustParticle;this.makeParticles('game',['dust0','dust1','dust2']);this.particleDrag.setTo(300,300);this.setAlpha(0.8,1.0);this.setRotation(0,0);this.minParticleScale=UIConstants.GAME_ASSET_SCALE*0.8;this.maxParticleScale=UIConstants.GAME_ASSET_SCALE*1.0;this.gravity=0;this.kill();this.visible=false;};UIRubbleEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UIRubbleEmitter.prototype.constructor=UIRubbleEmitter;UIRubbleEmitter.prototype.preUpdate=function(){if(!this.exists||this.game.physics.arcade.isPaused){return false;}return Phaser.Particles.Arcade.Emitter.prototype.preUpdate.call(this);};UIRubbleEmitter.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);if(this.countLiving()==0){this.kill();this.visible=false;}};UIRubbleEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UIRubbleEmitter.prototype.emit=function(x,y,rotation,speed){this.revive();this.visible=true;var speedX=Math.sin(rotation)*speed;var speedY=-Math.cos(rotation)*speed;speedX*=-UIConstants.RUBBLE_SMOKE_SPEED_SCALE;speedY*=-UIConstants.RUBBLE_SMOKE_SPEED_SCALE;if(Math.random()<0.5){x+=Math.cos(rotation)*-UIConstants.RUBBLE_TREAD_OFFSET*0.5;y+=Math.sin(rotation)*-UIConstants.RUBBLE_TREAD_OFFSET*0.5;}else{x+=Math.cos(rotation)*UIConstants.RUBBLE_TREAD_OFFSET*0.5;y+=Math.sin(rotation)*UIConstants.RUBBLE_TREAD_OFFSET*0.5;}this.minParticleSpeed.setTo(speedX-UIConstants.RUBBLE_SMOKE_RANDOM_SPEED,speedY-UIConstants.RUBBLE_SMOKE_RANDOM_SPEED);this.maxParticleSpeed.setTo(speedX+UIConstants.RUBBLE_SMOKE_RANDOM_SPEED,speedY+UIConstants.RUBBLE_SMOKE_RANDOM_SPEED);this.emitX=x;this.emitY=y;this.emitParticle();};UIRubbleEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};